import Box from '@cloudscape-design/components/box';
import Badge from '@cloudscape-design/components/badge';
import Container from '@cloudscape-design/components/container';
import Header from '@cloudscape-design/components/header';
import Link from '@cloudscape-design/components/link';
import SpaceBetween from '@cloudscape-design/components/space-between';
import glossaryData from '../data/glossary.json';
import sourcesData from '../data/cited-sources.json';
import { ACCESSED } from '../components/Cite';
import { sections } from '../lib/sections';

// Both lists are generated by revamp/tools/gen-sources.mjs: the glossary from the terms each
// section author recorded, the sources from the register entries the page cites.

interface Term {
  term: string;
  expansion: string | null;
  meaning: string;
  section: number;
}
interface Source {
  tier: number;
  url: string | null;
  local: string | null;
  venue: string | null;
  title: string;
  sections: number[];
  accessed?: string;
}

const TERMS = glossaryData as Term[];
const SOURCES = sourcesData as Source[];

const TIERS: Array<{ tier: number; name: string; what: string; color: 'green' | 'blue' | 'grey' | 'severity-low' }> = [
  { tier: 0, name: 'Tier 0', what: 'Our own measurements, each a single run on a named machine, logged in the repository.', color: 'green' },
  { tier: 1, name: 'Tier 1', what: 'Source code at a pinned tag or commit, official documentation and API references.', color: 'blue' },
  { tier: 2, name: 'Tier 2', what: "First-party vendor and lab posts. Their performance figures are the publisher's own claims.", color: 'grey' },
  { tier: 3, name: 'Tier 3', what: 'Papers, with the venue or the word preprint, and third-party technical analysis.', color: 'severity-low' },
];

function sectionTitle(n: number): string {
  return sections.find((s) => s.title.startsWith(`${n}. `))?.title ?? `${n}`;
}

export function GlossaryAndSources() {
  return (
    <SpaceBetween size="l">
      <Container
        header={
          <Header
            variant="h1"
            description="This section explains every acronym and term the dive uses, and lists every source it cites. The sources are grouped by tier, so you can see how much weight each one can carry."
          >
            30. Glossary and Sources
          </Header>
        }
      >
        <Box variant="p">
          The glossary gives the meaning each term has in this dive and the section that explains it. The source list holds the{' '}
          {SOURCES.length} sources behind the citations on the page. Each citation on the page shows the tier of its source, so you
          can tell a line of source code from a vendor&apos;s performance claim without opening the link.
        </Box>
      </Container>

      <Container
        header={
          <Header variant="h2" description="If you start reading in the middle of the dive, look up unfamiliar terms here. The last column shows the section that explains each term.">
            Glossary
          </Header>
        }
      >
        <div style={{ overflowX: 'auto' }}>
          <table style={{ borderCollapse: 'collapse', width: '100%' }}>
            <thead>
              <tr>
                <th style={{ textAlign: 'left', padding: '6px 10px', borderBottom: '2px solid #d5dbdb', minWidth: 120 }}>Term</th>
                <th style={{ textAlign: 'left', padding: '6px 10px', borderBottom: '2px solid #d5dbdb', minWidth: 240 }}>Meaning</th>
                <th style={{ textAlign: 'left', padding: '6px 10px', borderBottom: '2px solid #d5dbdb' }}>Explained in</th>
              </tr>
            </thead>
            <tbody>
              {TERMS.map((t) => (
                <tr key={t.term} data-num="glossary">
                  <td style={{ padding: '6px 10px', borderBottom: '1px solid #eaeded', verticalAlign: 'top' }}>
                    <Box variant="strong">{t.term}</Box>
                    {t.expansion && (
                      <Box variant="small" color="text-body-secondary">
                        {t.expansion}
                      </Box>
                    )}
                  </td>
                  <td style={{ padding: '6px 10px', borderBottom: '1px solid #eaeded', verticalAlign: 'top' }}>{t.meaning}</td>
                  <td style={{ padding: '6px 10px', borderBottom: '1px solid #eaeded', verticalAlign: 'top', whiteSpace: 'nowrap' }}>
                    section {t.section}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Container>

      {TIERS.map(({ tier, name, what, color }) => {
        const rows = SOURCES.filter((s) => s.tier === tier);
        if (rows.length === 0) return null;
        return (
          <Container
            key={tier}
            header={
              <Header variant="h2" description={what} counter={`(${rows.length})`}>
                Sources: {name}
              </Header>
            }
          >
            <ul style={{ margin: 0, paddingLeft: 18 }} data-num="sources">
              {rows.map((s) => (
                <li key={s.url ?? s.local ?? s.title} style={{ marginBottom: 6, overflowWrap: 'anywhere' }}>
                  <Badge color={color}>{name}</Badge>{' '}
                  {s.venue && (
                    <>
                      <Badge color="grey">{s.venue}</Badge>{' '}
                    </>
                  )}
                  {s.url ? (
                    <Link external href={s.url}>
                      {s.title}
                    </Link>
                  ) : (
                    <span>
                      {s.title} <Box variant="small" display="inline">(log in the repository: {s.local})</Box>
                    </span>
                  )}{' '}
                  <Box variant="small" display="inline" color="text-body-secondary">
                    (accessed {s.accessed ?? ACCESSED}; cited in section{s.sections.length > 1 ? 's' : ''} {s.sections.map((n) => sectionTitle(n).split('.')[0]).join(', ')})
                  </Box>
                </li>
              ))}
            </ul>
          </Container>
        );
      })}
    </SpaceBetween>
  );
}
